//! The desktop binary: calls the `run()` entry point `frus_shell::main!` generates in
//! the library. (On Android and the Web there is no binary: the entry point is
//! `android_main` or `start`, both generated by the same macro.)
//!
//! `cargo run -p frus-hello`; add `RUST_LOG=info` for logs.

#[cfg(not(any(target_os = "android", target_arch = "wasm32")))]
fn main() -> frus::anyhow::Result<()> {
    frus_hello::run()
}

#[cfg(any(target_os = "android", target_arch = "wasm32"))]
fn main() {}
